Retry with exponential backoff
def retry[T](fn: () => Future[T], maxRetries: Int = 3, delayMs: Long = 100): Future[T] = {
  fn().recoverWith { case ex =>
    if (maxRetries > 0) {
      Thread.sleep(delayMs)
      retry(fn, maxRetries - 1, delayMs * 2)
    } else {
      Future.failed(ex)
    }
  }
}

